        release.pop(timeout: 10)
        Invoices::ReservationOutcome.new(state: "prepared", conflicts: [], counts: {})
      },
      commit: committed,
      abort: Invoices::ReservationOutcome.new(state: "aborted", conflicts: [], counts: {})
    )
    save_pids = Queue.new
    recovery_pids = Queue.new

